create or replace procedure pr_select(
    p_ModifiedDate datetime,
    p_upperflag bit
)
returns result varchar;
language plpgsql
declare (
    result VARCHAR
)
begin
$$
    select p.FirstName
    into result
    from Person p
    where p.ModifiedDate > p_ModifiedDate;

    if bit = 1 then:
        upper(result)
end;
$$;

